@RestController
@RequestMapping("/api/documents")
public class DocumentController {

    @GetMapping(value = "/{id}", produces = "application/vnd.enterprise.document-v1+json")
    public ResponseEntity<DocumentV1Response> getDocumentV1(@PathVariable Long id) {
        DocumentV1Response doc = documentService.findV1(id);
        return ResponseEntity.ok().body(doc);
    }

    @GetMapping(value = "/{id}", produces = "application/vnd.enterprise.document-v2+json")
    public ResponseEntity<DocumentV2Response> getDocumentV2(@PathVariable Long id) {
        DocumentV2Response doc = documentService.findV2(id);
        return ResponseEntity.ok().header("Vary", "Accept").body(doc);
    }
}
